.wstacpro__tab th,.wstacpro__tab td{padding:12px 14px;border-bottom:1px solid #eee;text-align:center}.wstacpro__tab th{background:#1d2b4f!important;color:#fff!important;font-weight:700}.wstacpro__tab td:first-child,.wstacpro__tab th:first-child{text-align:left}
