.wstacpro__sred{display:grid;grid-template-columns:1fr minmax(240px,340px) 1fr;gap:36px;align-items:center;margin-top:18px}.wstacpro__sc{display:flex;flex-direction:column;gap:28px}.wstacpro__sf strong{display:block;font-size:19px;font-weight:800;margin:0 0 6px}.wstacpro__sf strong::after{content:'';display:inline-block;width:9px;height:9px;border-radius:50%;background:#d58a28;margin-left:8px;vertical-align:middle}.wstacpro__sf p{margin:0;font-size:15px;line-height:1.6;color:#333}.wstacpro__sm img,.wstacpro__sm video{width:100%;height:auto;display:block}
.wstacpro__karw{position:relative}.wstacpro__kar{grid-auto-flow:column;grid-auto-columns:calc((100% - 44px)/3);grid-template-columns:none!important;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none}.wstacpro__kar::-webkit-scrollbar{display:none}.wstacpro__kar>*{scroll-snap-align:start}
.wstacpro__pus{position:absolute;top:50%;transform:translateY(-50%);width:42px;height:42px;border-radius:50%;border:0;background:#fff;box-shadow:0 4px 14px rgba(0,0,0,.18);font-size:22px;line-height:42px;cursor:pointer;z-index:2;color:#1d2b4f;padding:0}.wstacpro__pus--l{left:-14px}.wstacpro__pus--d{right:-14px}
