@media (max-width:860px){.wstacpro__s{padding:38px 0}.wstacpro__dva{grid-template-columns:1fr;gap:22px}.wstacpro__dva--rev>div:first-child{order:0}
.wstacpro__sred{grid-template-columns:1fr;gap:22px}.wstacpro__sm{max-width:300px;margin:0 auto;order:-1}.wstacpro__g3,.wstacpro__g4,.wstacpro__g5{grid-template-columns:1fr 1fr}.wstacpro__red4{grid-template-columns:1fr 1fr}.wstacpro__plavo{margin-top:-38px}}
